import {randomUUID} from 'node:crypto'
import {performance} from 'node:perf_hooks'
import {inspect} from 'node:util'
import {getBatchResults} from './getBatchResults.js'
import {createStepHistory} from './step-history.js'

/**
 *
 * @param duration
 * @return {number}
 */
const durationToMs = (duration = {}) => {
  const {days = 0, hours = 0, minutes = 0, seconds = 0} = duration
  return (((days * 24 + hours) * 60 + minutes) * 60 + seconds) * 1000
}

/**
 *
 * @param args
 */
const formatArgs = (args) =>
  args.map((a) => (typeof a === 'string' ? a : inspect(a, {depth: null}))).join(' ')

/**
 * Runs a durable function handler
 * @param handler - callback being run
 * @param context - data to send to the operation
 * @param event - the step being run
 * @param [branchName] - the name of the branch being run
 * @param io
 */
export async function runDurable(handler, {context, event, branchName}, io) {
  const history = createStepHistory()
  let currentStep = null

  const streamLog = (level, args) => {
    const date = new Date()
    const timestamp = `${date.toLocaleDateString()} ${date.toLocaleTimeString()}`

    return io.emit({
      timestamp,
      kind: 'log',
      phase: 'log',
      step: currentStep,
      level,
      message: formatArgs(args),
    })
  }

  const logger = {
    log: (...a) => streamLog('info', a),
    info: (...a) => streamLog('info', a),
    warn: (...a) => streamLog('warn', a),
    error: (...a) => streamLog('error', a),
  }

  const emitFailure = (pending) => {
    history.settle(pending)
    io.emit(pending.event)
  }

  const settleUnretried = () => {
    const pending = history.getPending()
    if (pending !== null) {
      emitFailure(pending)
    }
  }

  const track = async (name, kind, produce, retry) => {
    settleUnretried()
    const {index, saved} = history.nextStep()

    if (saved?.phase === 'complete') {
      return saved.output
    }

    const maxAttempts = retry?.maxAttempts ?? 1
    const retries = Math.max((retry?.maxAttempts ?? 1) - 1, 0)
    const waitingOnRetry = typeof saved?.retryDelayMs === 'number'

    if (saved?.phase === 'error' && !waitingOnRetry) {
      throw saved.output
    }

    const attempt = (saved?.attempt ?? 0) + 1
    const prev = currentStep
    currentStep = name

    io.emit({name, kind, phase: 'start'})
    const startedAt = performance.now()

    try {
      const value = await produce(attempt)
      const completeEvent = {
        name,
        kind,
        phase: 'complete',
        output: value,
        durationMs: performance.now() - startedAt,
      }

      history.recordSuccess(index, completeEvent)
      io.emit(completeEvent)

      return value
    } catch (err) {
      const errorEvent = {
        name,
        kind,
        phase: 'error',
        error: {
          name: err?.name ?? 'Error',
          message: err?.message ?? String(err),
          stack: err?.stack ?? '',
        },
        durationMs: performance.now() - startedAt,
        attempt,
        retries,
        maxAttempts,
      }

      const retryPending = history.recordFailure(index, {
        event: errorEvent,
        error: err,
        delayMs: retry?.delay ? durationToMs(retry.delay) : 0,
      })

      if (!retryPending) {
        io.emit(errorEvent)
      }

      throw err
    } finally {
      currentStep = prev
    }
  }

  const FANOUT_STATUS = {
    STARTED: 'STARTED',
    ALL_COMPLETED: 'ALL_COMPLETED',
    FAILURE_TOLERANCE_EXCEEDED: 'FAILURE_TOLERANCE_EXCEEDED',
    SUCCEEDED: 'SUCCEEDED',
    FAILED: 'FAILED',
  }

  const step = {
    run: ({name, handler: fn, retry}) =>
      track(name || '', 'run', (attempt) => fn({logger, attempt}), retry),
    delegate: ({name, handler, event, retry}) =>
      track(
        name || '',
        'delegate',
        () => {
          const fn = typeof handler === 'string' ? handler : handler?.name
          if (!fn) {
            throw new Error('No function name provided for delegation')
          }
          return io.invoke(fn, event?.data ?? {})
        },
        retry,
      ),
    fanout: async ({name, branches}) => {
      if (
        !Array.isArray(branches) ||
        Array.from(branches).some((branch) => typeof branch !== 'function')
      ) {
        throw new TypeError('fanout branches must be an array of functions')
      }

      const outcomes = branches.map((_, index) => ({index, status: FANOUT_STATUS.STARTED}))
      return new Promise((resolve, reject) => {
        const execs = branches.map(async (branch, index) => {
          try {
            const branchName = `${name || 'fanout'} / branch ${index}`
            const result = await runDurable(branch, {context, event, branchName}, io)
            outcomes[index] = {index, status: FANOUT_STATUS.SUCCEEDED, result}
          } catch (err) {
            const error = err instanceof Error ? err : new Error(String(err))
            outcomes[index] = {index, status: FANOUT_STATUS.FAILED, error}
          }
        })

        Promise.allSettled(execs)
          .then(() => {
            resolve(getBatchResults(outcomes, FANOUT_STATUS.ALL_COMPLETED))
          })
          .catch(() => {
            reject(reject)
          })
      })
    },
    waitForCondition: ({name, initial, poller, next}) =>
      track(name || '', 'wait-for-condition', async () => {
        let state = initial
        let attempt = 1
        let polling = true
        while (polling) {
          state = await poller(state, {logger, attempt})
          const decision = next(state, {attempt})
          if (decision.shouldRetry) {
            await io.wait(durationToMs(decision.delay))
            attempt += 1
          } else {
            polling = false
          }
        }
        return state
      }),
    waitForCallback: ({name, submitter, timeout, retry}) => {
      return track(
        name || '',
        'wait-for-callback',
        async () => {
          const callbackId = randomUUID()
          const result = io.registerCallback({
            callbackId,
            name,
            timeout: durationToMs(timeout),
          })
          io.emit({name, kind: 'wait-for-callback', phase: 'waiting', callbackId})
          try {
            await submitter({callbackId, logger})
          } catch (err) {
            io.cancelCallback(callbackId)
            throw err
          }

          return await result
        },
        retry,
      )
    },
    wait: ({name, duration}) =>
      track(name || '', 'wait', async () => {
        await io.wait(durationToMs(duration))
        return undefined
      }),
  }

  let result
  let done = false
  const handlerArgs = branchName !== undefined ? {step, logger} : {context, event, step, logger}
  while (!done) {
    history.startRun()
    try {
      result = await handler(handlerArgs)
      settleUnretried()
      done = true
    } catch (err) {
      const pending = history.getPending()
      if (pending === null) {
        throw err
      }
      if (err?.name === 'UnrecoverableError') {
        emitFailure(pending)
        throw err
      }
      io.emit({...pending.event, retryDelayMs: pending.delayMs})
      await io.wait(pending.delayMs)
    }
  }

  return result
}
